-- MH-576 D7: one single-tenant instance of a product — its own app (own container(s), own env,
-- own hostname), optionally its own data-service database (internal/dbsvc). app_id is set once
-- CreateApp succeeds (null while provisioning or after a failed provision). status: provisioning,
-- active, suspended, failed, destroyed. customer_ref is opaque, set by whoever provisioned it (a
-- team member or a product key) — it is the billing system's own customer id, never interpreted.
CREATE UNIQUE INDEX product_instances_product_name_key ON product_instances (product_id, name);
CREATE INDEX product_instances_team_idx ON product_instances (team_id, created_at);
CREATE INDEX product_instances_product_idx ON product_instances (product_id);
